```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Mapa de conversión de Markdown a HTML
const std::unordered_map<std::string, std::string> md2html{
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"`", "<code>"},
    {"**", "<strong>"},
    {"*", "<em>"},
    {"[", "<a href="},
    {"]", ">"),
    {"<", "&lt;"},
    {">", "&gt;"},
    {"\\n", "<br/>"},
};

// Función para convertir texto con formato Markdown a HTML
std::string md_to_html(std::string& markdown) {
    std::string html;

    // Reemplazar los enlaces
    std::regex link_regex("\\[(.+?)\\]\\((.+?)\\)");
    std::smatch match;
    while (std::regex_search(markdown, match, link_regex)) {
        std::string link_text = match[1];
        std::string link_url = match[2];
        std::string link_html = md2html.at("[") + link_url + "](" + link_url + ")";
        markdown.replace(match.position(), match.length(), link_html);
    }

    // Convertir texto con formato Markdown a HTML
    for (const auto& pair : md2html) {
        std::string md_token = pair.first;
        std::string html_token = pair.second;
        std::regex regex(md_token);
        std::string::const_iterator start, end;
        while ((start = std::search(markdown.begin(), markdown.end(), regex.begin(), regex.end(), std::equal_to<>())) != markdown.end()) {
            end = start + std::distance(regex.begin(), regex.end());
            std::string token = std::string(start, end);
            html += html_token;
            markdown.erase(start, end);
        }
    }

    // Añadir etiquetas HTML restantes
    html += markdown;

    return html;
}

int main() {
    std::string markdown = "Este es un **texto** con # título y enlaces [Google](https://www.google.com/).";
    std::string html = md_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

La función `md_to_html` utiliza una tabla hash `md2html` para convertir los tokens de Markdown a sus equivalentes HTML. También se utiliza una expresión regular para reemplazar los enlaces en el texto.

Ejemplo de uso:

