def longest_common_subsequence(str1, str2):
    m, n = len(str1), len(str2)
    # Initialize a 2D table to store subproblem solutions
    table = [[0] * n for _ in range(m)]

    # Fill in the table using dynamic programming
    for I in range(m):
        for j in range(n):
            if I == 0 or j == 0:
                table[i][j] = 0
            elif str1[i] == str2[j]:
                table[i][j] = table[i-1][j-1] + 1
            else:
                table[i][j] = max(table[i-1][j], table[i][j-1])

    # Extract the longest common subsequence from the table
    result = ""
    I, j = m - 1, n - 1
    while I >= 0 and j >= 0:
        if I == 0 or j == 0:
            break
        elif str1[i] == str2[j]:
            result = str1[i] + result
            I -= 1
            j -= 1
        elif table[i-1][j] > table[i][j-1]:
